Ext.define('BNK.view.Budget.bgx.BgxNfmAply01MViewController', {
    extend: 'BaseViewController',
    alias: 'controller.BgxNfmAply01MViewController',

    config: {
        viewId: 'BgxNfmAply01M'
    },

    /* 목록 조회 */
    onSelect: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            dateCnt = refs.dateStartEndContainer,
            dateCntRef = dateCnt.getReferences(),
            dateCntCtrl = dateCnt.controller,
            strdt = dateCntRef.strdt,
            edt = dateCntRef.edt,
            aplStcd = refs.aplStcd,
            aplKndcd = refs.aplKndcd,
            params = {},
            store = refs.grid_container.getViewModel().storeInfo.ExpListStore;
        //     store = vm.storeInfo.ExpListStore;

        params.aplEmpId = SecurityUtils.getPrincipal().hrHrpmEmpId;

        // 조회기간
        var result = dateCntCtrl.dateValid();
        if (result != '') {
            Ext.Msg.alert('알림', result);
            return;
        } else {
            params.inbizStartdt = Ext.Date.format(strdt.getValue(), 'Ymd');
            params.inbizEnddt = Ext.Date.format(edt.getValue(), 'Ymd');
        }

        // 신청분류
        if (aplKndcd && aplKndcd.getValue() && aplKndcd.getValue() != '99') {
            params.aplKndcd = aplKndcd.getValue();
        }

        // 신청상태
        if (aplStcd && aplStcd.getValue() && aplStcd.getValue() != '99') {
            params.aplStcd = aplStcd.getValue();
        }


        store.getProxy().extraParams = params;
        store.removeAll();
        store.loadPage(1);
    },

    /* 결재이력조회 */
    fnChangeApplyForm: function(data, readOnlyFlag) {
        var  me = this,
             naviView = me.getView().up('navigationview');

        if (readOnlyFlag && data && data.applyInfo) {
            var applyInfo = data.applyInfo;
            switch (applyInfo.aplKndcd) {
                case Constants.aplKndcd.CARD : 		// 법인카드
                    break;
                case Constants.aplKndcd.CSH_RCT : 	// 현금영수증
                    break;
                case Constants.aplKndcd.ETC_RCT : 	// 기타영수증
                    break;
                case Constants.aplKndcd.TXINV : 	// 세금계산서
                case Constants.aplKndcd.XPNS : 		// 여비정산서
                    Ext.Msg.alert('알림', '세금계산서와 여비정산서는 PC에서만 조회가능합니다.');
                    return;
                    default :
                    return;
            }

            data.readOnlyFlag = readOnlyFlag;
            me.PUSH_VIEW(naviView, {
                menuId  : 'BgxNfmAply02M',
                title   : '결의서 작성',
                isSubView : true,
                data : data
            });
        }
    },

    onBtnSelect: function(button, e, eOpts) {
        this.onSelect();
    },

    onComboboxCollapse: function(field, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            newValue = field.getValue();

        if (!newValue) {
            return;
        }

        switch(newValue) {
            case Constants.aplKndcd.TXINV : 	// 세금계산서
            case Constants.aplKndcd.XPNS : 		// 여비정산서
            Ext.Msg.alert('알림', '세금계산서와 여비정산서 상세내역은 PC에서만 조회가능하오니 참고바랍니다.');
            break;
        }
    },

    /* 결의서 작성 */
    onBtnWrite: function(button, e, eOpts) {
        var me = this,
            naviView = me.getView().up('navigationview');

        me.PUSH_VIEW(naviView, {
            menuId  : 'BgxNfmAply02M',
            title   : '결의서 작성',
            isSubView : true,
        });
    },

    /* 초기화 */
    onContainerInitialize: function(component, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            cbxAplStcd = refs.aplStcd,
            cbxAplKndcd = refs.aplKndcd,
            store = cbxAplStcd.getStore(),
            date = new Date(),
            dateContainer = refs.dateStartEndContainer,
            dateRefs = dateContainer.getReferences(),
            strdt = dateRefs.strdt,
            edt = dateRefs.edt;

        // 신청상태 초기화
        store.getAt(0).set('text', '전 체');
        store.getAt(0).set('value', '99');
        cbxAplStcd.setValue('99');

        store = cbxAplKndcd.getStore();
        // 신청분류 초기화
        store.getAt(0).set('text', '전 체');
        store.getAt(0).set('value', '99');
        cbxAplKndcd.setValue('99');

        // 조회기간 초기화
        edt.setValue(DateUtils.parseDate(date));
        date.setMonth(date.getMonth() - 1);
        strdt.setValue(DateUtils.parseDate(date));

        refs.grid_container.refs.grid.el.select('.x-headercontainer').setStyle('height',	'0px');
        me.onSelect();
    }

});